			tierIconLabel.setIcon(icon);
			tierIconLabel.setToolTipText(achievement.getTier() + " Tier");
		}
		else
		{
			log.warn("Could not load tier icon for {}", achievement.getTier());
			tierIconLabel.setIcon(null);
		}
	}

	private Color getNameColor()
